const tabId = 2136412301;
const snapshot = await browser.snapshot({ tabId });
const lines = snapshot.text.split("\n");

// Find all hotel headings and ratings
const hotelEntries = [];
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (line.includes('heading "') && line.includes('level="2"')) {
    const nameMatch = line.match(/heading "(.*?)"/);
    const name = nameMatch ? nameMatch[1] : line;
    // Look ahead 15 lines for price and rating
    const ahead = lines.slice(i, i + 15).join(" ");
    const priceMatch = ahead.match(/\$(\d+)/);
    const ratingMatch = ahead.match(/(\d\.\d)\s+out of 5 stars/);
    const reviewsMatch = ahead.match(/from\s+([\d,]+)\s+reviews/);
    hotelEntries.push({
      name,
      price: priceMatch ? `$${priceMatch[1]}` : null,
      rating: ratingMatch ? ratingMatch[1] : null,
      reviews: reviewsMatch ? reviewsMatch[1] : null,
      lineIndex: i
    });
  }
}

console.log("Hotel entries found:", hotelEntries);

