const tabId = 2136412401;

const products = await browserjs(tabId, () => {
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  return Array.from(items).map(item => {
    const titleEl = item.querySelector('h2 span, h2 a span');
    const linkEl = item.querySelector('h2 a');
    const priceWhole = item.querySelector('.a-price-whole')?.textContent?.trim();
    const priceFraction = item.querySelector('.a-price-fraction')?.textContent?.trim();
    const ratingEl = item.querySelector('.a-icon-alt');
    const reviewsEl = item.querySelector('span[aria-label*="reviews"], a span.a-size-base');
    const asin = item.getAttribute('data-asin');

    let price = null;
    if (priceWhole) {
      price = `$${priceWhole}${priceFraction ? '.' + priceFraction : ''}`;
    }

    return {
      title: titleEl?.textContent?.trim(),
      price,
      rating: ratingEl?.textContent?.trim(),
      reviews: reviewsEl?.textContent?.trim(),
      asin,
      link: linkEl ? (linkEl.href.startsWith('http') ? linkEl.href : 'https://www.amazon.com' + linkEl.getAttribute('href')) : null
    };
  }).filter(p => p.title && p.price);
});

console.log("Found Amazon products:", products.length);
console.log("First 8 products:", JSON.stringify(products.slice(0, 8), null, 2));

