const tabIds = [2136412402, 2136412403, 2136412404];

const productDetails = [];

for (const tabId of tabIds) {
  const data = await browserjs(tabId, () => {
    const title = document.querySelector('#productTitle')?.textContent?.trim();
    const priceWhole = document.querySelector('.a-price .a-price-whole')?.textContent?.trim();
    const priceFraction = document.querySelector('.a-price .a-price-fraction')?.textContent?.trim();
    const priceOffscreen = document.querySelector('.a-price .a-offscreen')?.textContent?.trim();
    const rating = document.querySelector('#acrPopover')?.getAttribute('title') || document.querySelector('.a-icon-alt')?.textContent?.trim();
    const reviewCount = document.querySelector('#acrCustomerReviewText')?.textContent?.trim();

    // Feature bullets
    const bullets = Array.from(document.querySelectorAll('#feature-bullets li span.a-list-item')).map(b => b.textContent.trim()).filter(b => b.length > 5);

    return {
      title,
      price: priceOffscreen || (priceWhole ? `$${priceWhole}.${priceFraction || '00'}` : null),
      rating,
      reviewCount,
      bullets: bullets.slice(0, 5),
      url: window.location.href
    };
  });
  productDetails.push({ tabId, ...data });
}

console.log("Product Details:\n", JSON.stringify(productDetails, null, 2));

